import type { FilterDataStructure } from 'models/Filters';

/**
 * WatchTower presets include a `watch_tower_brands` block (BFF shape).
 * Shared filter configs use this to apply null baselines instead of Commercial
 * Results "All" sentinels or first-option defaults.
 */
export function isWatchTowerFilterData(
  filterData: FilterDataStructure,
): boolean {
  return filterData.watch_tower_brands != null;
}
